import { readFileSync } from "node:fs";
import { join } from "node:path";
import { describe, expect, it } from "vitest";

/**
 * Guards the `retention-days: 1` JsonPatch in `lib/app.ts`.
 *
 * `deploy.yml` is generated by cdk-pipelines-github, which hardcodes the
 * `with:` block of the cdk.out upload and exposes no retention option — so the
 * setting is applied as an RFC 6902 patch at a POSITIONAL step index
 * (`/jobs/Build-Synth/steps/2/with/retention-days`).
 *
 * A construct upgrade that reorders the steps usually throws at synth, because
 * most steps have no `with:` block to add a key to. But if the step landing at
 * index 2 does have one, the patch would apply silently to the WRONG step and
 * the ~33 MB cdk.out upload would quietly revert to the repo's 90-day default
 * — which is what exhausts the org's 2 GB shared Actions storage and blocks
 * every deploy. This test closes that gap by pinning the setting to the
 * cdk.out upload itself rather than to an index.
 */

const DEPLOY_YML = join(__dirname, "../../../.github/workflows/deploy.yml");

describe("deploy.yml cdk.out artifact retention", () => {
  const yaml = readFileSync(DEPLOY_YML, "utf8");

  // The generated step block, from its `- name:` line up to the next step or
  // job at the same or lower indentation.
  const uploadStep = yaml.match(
    /^ {6}- name: Upload cdk\.out\n(?: {8}.*\n| *\n)*/m,
  )?.[0];

  it("still emits an Upload cdk.out step", () => {
    expect(uploadStep, "Upload cdk.out step not found in deploy.yml").toBeDefined();
  });

  it("caps that upload at 1 day", () => {
    expect(uploadStep).toContain("retention-days: 1");
  });

  it("puts retention-days on that step and nowhere else", () => {
    // If the positional patch index drifts onto another step, the count stays
    // at 1 but the match above fails; if a second upload appears, this fires.
    const occurrences = yaml.match(/retention-days:/g) ?? [];
    expect(occurrences).toHaveLength(1);
  });

  it("has exactly one artifact upload to keep the patch unambiguous", () => {
    const uploads = yaml.match(/uses: actions\/upload-artifact/g) ?? [];
    expect(uploads).toHaveLength(1);
  });
});
